import os
import uuid
from typing import Any, Dict, Text

import boto3
import structlog
from botocore.exceptions import BotoCoreError, ClientError

MARKETPLACE_ENABLED_ENV_VAR = "RASA_AWS_MARKETPLACE_ENABLED"
MARKETPLACE_PRODUCT_ID_ENV_VAR = "RASA_AWS_MARKETPLACE_PRODUCT_ID"

AWS_MARKETPLACE_KEY_FINGERPRINT = "aws:294406891311:AWS/Marketplace:issuer-fingerprint"
CHECKOUT_TYPE = "PROVISIONAL"
ENTITLEMENT_NAME = "AWS::Marketplace::Usage"

structlogger = structlog.get_logger()


class MarketplaceLicenseValidationException(Exception):
    """Raised when AWS Marketplace license checkout validation fails."""


def is_marketplace_licensing_enabled() -> bool:
    """Return whether AWS Marketplace licensing is enabled via environment."""
    return os.environ.get(MARKETPLACE_ENABLED_ENV_VAR, "").strip().lower() == "true"


def validate_marketplace_license() -> None:
    """Validate an active AWS Marketplace subscription at server startup.

    No-op when :func:`is_marketplace_licensing_enabled` is false. Otherwise
    performs a PROVISIONAL CheckoutLicense call and validates the response.
    Uses the default boto3 credential chain.

    Raises:
        SystemExit: When checkout fails or entitlements are invalid.
    """
    if not is_marketplace_licensing_enabled():
        return

    checkout_request = _build_checkout_request()
    product_id = checkout_request["ProductSKU"]

    license_client = boto3.client("license-manager")

    try:
        response = license_client.checkout_license(**checkout_request)
    except ClientError as error:
        error_code = error.response.get("Error", {}).get("Code", "ClientError")
        _log_checkout_failure(error_code, product_id)
        raise SystemExit(
            "Failed to validate AWS Marketplace license. "
            "Ensure the deployment has a valid Marketplace subscription "
            f"and that `{MARKETPLACE_PRODUCT_ID_ENV_VAR}` is set to the "
            "Product ID from the AWS Marketplace Management Portal."
        ) from error
    except BotoCoreError as error:
        _log_checkout_failure(type(error).__name__, product_id)
        raise SystemExit(
            "Failed to validate AWS Marketplace license due to an AWS client error. "
            "Verify IAM credentials and network connectivity."
        ) from error

    try:
        _validate_entitlements_allowed(response)
    except MarketplaceLicenseValidationException as error:
        _log_checkout_failure(str(error), product_id)
        raise SystemExit(
            "Failed to validate AWS Marketplace license. "
            f"The subscription does not include the required '{ENTITLEMENT_NAME}' "
            "entitlement."
        ) from error

    _log_checkout_verified(product_id)


def _build_checkout_request() -> Dict[Text, Any]:
    """Build the CheckoutLicense request payload from environment variables.

    Returns:
        Request kwargs for license-manager CheckoutLicense.

    Raises:
        SystemExit: When required environment variables are missing.
    """
    product_id = os.environ.get(MARKETPLACE_PRODUCT_ID_ENV_VAR, "").strip()
    if not product_id:
        _log_checkout_failure("MissingProductId", "")
        raise SystemExit(
            f"AWS Marketplace licensing is enabled but "
            f"`{MARKETPLACE_PRODUCT_ID_ENV_VAR}` is not set. "
            "Set it to the Product ID from the AWS Marketplace Management Portal."
        )

    return {
        "ProductSKU": product_id,
        "CheckoutType": CHECKOUT_TYPE,
        "KeyFingerprint": AWS_MARKETPLACE_KEY_FINGERPRINT,
        "Entitlements": [{"Name": ENTITLEMENT_NAME, "Unit": "None"}],
        "ClientToken": str(uuid.uuid4()),
    }


def _validate_entitlements_allowed(response: Dict[Text, Any]) -> None:
    """Validate CheckoutLicense response entitlements.

    Expects entitlements under ``EntitlementsAllowed``, for example::

        {
            "EntitlementsAllowed": [
                {"Name": "AWS::Marketplace::Usage", "Value": "active"}
            ]
        }

    Args:
        response: CheckoutLicense API response.

    Raises:
        MarketplaceLicenseValidationException: When the required entitlement is missing
            or has an empty Value.
    """
    entitlements_allowed = response.get("EntitlementsAllowed") or []
    for entitlement in entitlements_allowed:
        name = entitlement.get("Name")
        if (
            not isinstance(name, str)
            or name.strip().lower() != ENTITLEMENT_NAME.lower()
        ):
            continue
        value = entitlement.get("Value")
        if value:
            return
        raise MarketplaceLicenseValidationException("EmptyEntitlementValue")

    raise MarketplaceLicenseValidationException("MissingEntitlement")


def _log_checkout_failure(error_code: Text, product_id: Text) -> None:
    structlogger.error(
        "license.marketplace.checkout.failed",
        error_code=error_code,
        product_id=product_id,
        dimension=ENTITLEMENT_NAME,
    )


def _log_checkout_verified(product_id: Text) -> None:
    structlogger.info(
        "license.marketplace.checkout.verified",
        product_id=product_id,
        dimension=ENTITLEMENT_NAME,
    )
